#include <bits/stdc++.h>
using namespace std;

using i64 = long long;
using f80 = long double;
using u64 = unsigned long long;

const int dX[] = {1, -1, 0, 0};
const int dY[] = {0, 0, 1, -1};

int N, T, srcX, srcY;
string gridLab[20], gridSci[20];
int memo[12][12][12][12][62];
int capacity[250][250], parent[250];
int distance[20][20], visited[20][20];

inline bool isValid(int x, int y){
	return 0 <= x && x < N && 0 <= y && y < N && gridLab[x][y] != 'Y' && gridLab[x][y] != 'Z';
}

void bfsPrecompute(){
	memset(distance, 0x3f, sizeof(distance));
	memset(visited, 0, sizeof(visited));
	distance[srcX][srcY] = 0;
	visited[srcX][srcY] = 1;
	queue<int> qx, qy;
	qx.push(srcX);
	qy.push(srcY);
	while(!qx.empty()){
		int x = qx.front(); qx.pop();
		int y = qy.front(); qy.pop();
		for(int k = 0; k < 4; k++){
			int nx = x + dX[k];
			int ny = y + dY[k];
			if(isValid(nx, ny) && !visited[nx][ny]){
				distance[nx][ny] = distance[x][y] + 1;
				visited[nx][ny] = 1;
				qx.push(nx);
				qy.push(ny);
			}
		}
	}
}

int dfsPath(int x0, int y0, int x1, int y1, int step){
	if(step > T)return 0;
	int &res = memo[x0][y0][x1][y1][step];
	if(res != -1)return res;
	if(x0 == x1 && y0 == y1)return distance[x0][y0] >= step;
	if(distance[x0][y0] <= step)return res = 0;
	for(int k = 0; k < 4; k++){
		int nx = x0 + dX[k];
		int ny = y0 + dY[k];
		if(isValid(nx, ny) && dfsPath(nx, ny, x1, y1, step + 1))return res = 1;
	}
	return res = 0;
}

bool bfs(int source, int sink){
	memset(parent, -1, sizeof(parent));
	parent[source] = -2;
	queue<int> q;
	q.push(source);
	while(!q.empty()){
		int v = q.front(); q.pop();
		for(int i = source; i <= sink; i++){
			if(parent[i] == -1 && capacity[v][i] > 0){
				parent[i] = v;
				q.push(i);
			}
		}
	}
	return parent[sink] != -1;
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout<<fixed<<setprecision(32);

	cin>>N>>T;
	for(int i = 0; i < N; i++){
		cin>>gridSci[i];
	}
	for(int i = 0; i < N; i++){
		cin>>gridLab[i];
	}
	vector<pair<int, int>> positions;
	vector<int> labCap, sciCap;
	for(int i = 0; i < N; i++){
		for(int j = 0; j < N; j++){
			if(gridSci[i][j] == 'Z'){
				srcX = i;
				srcY = j;
			}else if('0' <= gridSci[i][j] && gridSci[i][j] <= '9'){
				positions.emplace_back(i, j);
				labCap.push_back(gridLab[i][j] - '0');
				sciCap.push_back(gridSci[i][j] - '0');
			}
		}
	}
	int M = positions.size();
	memset(capacity, 0, sizeof(capacity));
	for(int i = 0; i < M; i++){
		capacity[0][i + 1] = sciCap[i];
		capacity[M + 1 + i][2*M + 1] = labCap[i];
	}
	bfsPrecompute();
	memset(memo, -1, sizeof(memo));
	for(int i = 0; i < M; i++){
		for(int j = 0; j < M; j++){
			if(dfsPath(positions[i].first, positions[i].second, positions[j].first, positions[j].second, 0)){
				capacity[i + 1][M + 1 + j] = 1000;
			}
		}
	}
	int maxFlow = 0;
	while(bfs(0, 2*M + 1)){
		int sink = 2*M + 1;
		int bottleneck = 1e6;
		while(parent[sink] >= 0){
			bottleneck = min(bottleneck, capacity[parent[sink]][sink]);
			sink = parent[sink];
		}
		sink = 2*M + 1;
		while(parent[sink] >= 0){
			capacity[parent[sink]][sink] -= bottleneck;
			capacity[sink][parent[sink]] += bottleneck;
			sink = parent[sink];
		}
		maxFlow += bottleneck;
	}
	cout<<maxFlow;

	return 0;
}
